<script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api}from'../api';const staff=ref([]),admins=ref([]),dialog=ref(false);let form=reactive({id:null,username:'',password:'',name:'',status:0});const load=async()=>{[staff.value,admins.value]=await Promise.all([api.staff(),api.admins()])};onMounted(load);function edit(x={}){Object.assign(form,{id:null,username:'',password:'',name:'',status:0},x);dialog.value=true}async function save(){await api.saveAdmin(form.id,form);ElMessage.success('账号已保存');dialog.value=false;load()}async function revoke(x){await ElMessageBox.confirm(`取消 ${x.nickname||x.phone} 的现场权限？`,'权限确认');await api.revoke(x.id);load()}async function disable(x){await api.disableAdmin(x.id);load()}</script>
<template><div class="page-head"><div><h2>权限与账号</h2><p>小程序现场角色与 Web 管理账号相互独立</p></div><el-button type="primary" @click="edit()">新增 Web 管理员</el-button></div><div class="panel" style="margin-bottom:20px"><h3>小程序工作人员</h3><el-table :data="staff"><el-table-column prop="nickname" label="会员"/><el-table-column prop="phone" label="手机号"/><el-table-column label="角色"><template #default="{row}"><el-tag>{{row.staffRole==='admin'?'小程序管理员':'核销员'}}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="注册时间"/><el-table-column label="操作"><template #default="{row}"><el-button link type="danger" @click="revoke(row)">取消权限</el-button></template></el-table-column></el-table></div><div class="panel"><h3>Web 管理账号</h3><el-table :data="admins"><el-table-column prop="username" label="用户名"/><el-table-column prop="name" label="姓名"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status?'danger':'success'">{{row.status?'禁用':'正常'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button v-if="!row.status" link type="danger" @click="disable(row)">禁用</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="form.id?'编辑管理员':'新增管理员'" width="460px"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item :label="form.id?'新密码（不修改请留空）':'密码（至少 12 位）'"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="0" :inactive-value="1" active-text="正常" inactive-text="禁用"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
